// 作者基准指标：与 tools/author_baseline_v2.py 的统计口径保持同构。
// 只统计 CJK 字符；句子按 。！？ 与换行切分；段落按空行/换行切分。

function countCjk(text) {
  return (text.match(/[\u3400-\u9fff\uf900-\ufaff]/g) || []).length
}

function splitSentences(body) {
  return body
    .split(/[。！？!?；;…\n]+/)
    .map((sentence) => sentence.trim())
    .filter((sentence) => /[\u3400-\u9fff\uf900-\ufaff]/.test(sentence))
}

function splitParagraphs(body) {
  return body
    .split(/\n+/)
    .map((paragraph) => paragraph.trim())
    .filter(Boolean)
}

function sentenceLengths(body) {
  return splitSentences(body).map((sentence) => countCjk(sentence))
}

function paragraphLengths(body) {
  return splitParagraphs(body).map((paragraph) => countCjk(paragraph))
}

function coefficientOfVariation(values) {
  if (values.length === 0) return 0
  const mean = values.reduce((sum, value) => sum + value, 0) / values.length
  if (mean === 0) return 0
  const variance = values.reduce((sum, value) => sum + (value - mean) ** 2, 0) / values.length
  return Math.sqrt(variance) / mean
}

function startRepeatRatio(starts) {
  if (starts.length < 2) return 0
  const seen = new Set()
  let repeated = 0
  for (const start of starts) {
    if (seen.has(start)) repeated += 1
    else seen.add(start)
  }
  return repeated / starts.length
}

function duplicateSentenceRatio(body) {
  const normalized = splitSentences(body).map((sentence) => normalizeCjk(sentence))
  if (normalized.length === 0) return 0
  return (normalized.length - new Set(normalized).size) / normalized.length
}

function repeatedFourGramRatio(body) {
  let total = 0
  const grams = new Set()
  for (const sentence of splitSentences(body)) {
    const normalized = normalizeCjk(sentence)
    if (normalized.length < 8) continue
    for (let i = 0; i + 4 <= normalized.length; i += 1) {
      total += 1
      grams.add(normalized.slice(i, i + 4))
    }
  }
  return total === 0 ? 0 : (total - grams.size) / total
}

function normalizeCjk(text) {
  return (text.match(/[\u3400-\u9fff\uf900-\ufaff]/g) || []).join("")
}

function cjkStarts(values) {
  const starts = []
  for (const value of values) {
    const match = value.match(/[\u3400-\u9fff\uf900-\ufaff]/)
    if (match) starts.push(value.slice(match.index, match.index + 2))
  }
  return starts
}

function adjacentLengthVolatility(lengths) {
  if (lengths.length < 2) return 0
  let sum = 0
  for (let i = 1; i < lengths.length; i += 1) {
    sum += Math.abs(lengths[i] - lengths[i - 1]) / Math.max(lengths[i - 1], 1)
  }
  return sum / (lengths.length - 1)
}

function countWordList(text, words) {
  let count = 0
  for (const word of words) count += text.split(word).length - 1
  return count
}

function median(values) {
  if (values.length === 0) return 0
  const sorted = [...values].sort((a, b) => a - b)
  const middle = Math.floor(sorted.length / 2)
  return sorted.length % 2 === 0 ? (sorted[middle - 1] + sorted[middle]) / 2 : sorted[middle]
}

function computeBaselineMetrics(body) {
  const chineseChars = countCjk(body)
  if (chineseChars < 800) {
    return { chineseChars, enabled: false }
  }
  const sentences = splitSentences(body)
  const paragraphs = splitParagraphs(body)
  const sentenceLengthValues = sentenceLengths(body)
  const paragraphLengthValues = paragraphLengths(body)
  return {
    chineseChars,
    enabled: true,
    sentence_start_repeat_ratio: startRepeatRatio(cjkStarts(sentences)),
    paragraph_start_repeat_ratio: startRepeatRatio(cjkStarts(paragraphs)),
    duplicate_sentence_ratio: duplicateSentenceRatio(body),
    repeated_four_gram_ratio: repeatedFourGramRatio(body),
    sentence_length_cv: coefficientOfVariation(sentenceLengthValues),
    paragraph_length_cv: coefficientOfVariation(paragraphLengthValues),
    adjacent_length_volatility: adjacentLengthVolatility(paragraphLengthValues),
    clause_per_sentence: (body.match(/[，；、,;]/g) || []).length / Math.max(1, sentences.length),
    exclamation_per_1000: (body.match(/[！!]/g) || []).length / chineseChars * 1000,
    ellipsis_per_1000: (body.match(/……|…/g) || []).length / chineseChars * 1000,
    semicolon_count: (body.match(/[；;]/g) || []).length,
    semicolon_per_1000: (body.match(/[；;]/g) || []).length / chineseChars * 1000,
    pause_per_1000: (body.match(/[、]/g) || []).length / chineseChars * 1000,
    sensory_word_per_1000: countWordList(body, ["看见", "听见", "闻到", "尝到", "触到", "视线", "目光", "气味", "声音", "光", "冷", "热", "疼", "痛", "麻"]) / chineseChars * 1000,
    connective_per_1000: countWordList(body, ["但是", "可是", "然而", "因此", "所以", "于是", "然后", "接着", "顿时", "随即", "与此同时", "紧接着"]) / chineseChars * 1000,
    dialogue_verb_per_1000: countWordList(body, ["说", "问", "道", "答", "喊", "叫", "回", "开口", "低声", "沉声", "笑道", "说道"]) / chineseChars * 1000,
    action_word_per_1000: countWordList(body, ["走", "跑", "抓", "推", "拉", "拿", "放", "转", "退", "避", "挡", "砸", "劈", "刺", "砍", "跃", "扑", "撞", "握", "指"]) / chineseChars * 1000,
    matter_word_per_1000: countWordList(body, ["石", "木", "铁", "灯", "水", "火", "门", "窗", "桌", "椅", "墙", "路", "车", "纸", "瓶", "刀", "枪", "布", "衣", "土"]) / chineseChars * 1000,
    abstract_word_per_1000: countWordList(body, ["规矩", "秩序", "意义", "身份", "资格", "计划", "策略", "结构", "系统", "规则", "概念", "判断", "结论", "价值"]) / chineseChars * 1000,
    dialogue_action_per_1000: countWordList(body, ["笑", "皱眉", "点头", "摇头", "瞪", "盯", "挥手", "摆手", "沉默", "停顿"]) / chineseChars * 1000,
    simile_per_1000: (body.match(/像/g) || []).length / chineseChars * 1000,
    type_token_ratio: new Set((body.match(/[\u3400-\u9fff\uf900-\ufaff]/g) || [])).size / chineseChars,
    pronoun_per_1000: countWordList(body, ["他", "她", "它", "自己"]) / chineseChars * 1000,
    interior_sentence_length_cv: coefficientOfVariation(sentenceLengthValues.slice(1, -1)),
    interior_paragraph_median: median(paragraphLengthValues.slice(1, -1))
  }
}

module.exports = {
  computeBaselineMetrics
}

【降AI方法指导 - 创作执行】
执行角色：生成前方法指导；不修改请求产物，不做裁判，不输出总分。
风格卡片是唯一风格 owner；本指导只是默认方法，不覆盖风格选择。
叙事缺口按 SKILL 契约上报，不擅自补设因果。
方法边界：短句只用于关键转折，连续碎片不是风格。判断标准是读起来更像活人叙事，不是命中更少检测词。
事件表达：情绪、判断和关系写成可见行为。优先用动作变化、选择性和信息顺序呈现，不用评论腔解释。
叙事用笔：视角带判断：看什么不看什么、语气倾向和节奏轻重。同一段视角一致，紧张场景收短，舒缓场景铺长。
对白轻重：对白留残缺和轻重，有些回合只有动作，有些只有台词。不替读者总结因果，不写解释性从句。
风格优先：风格卡片与声纹优先于本指导；有冲突时按风格执行。方法只补默认路径，不覆盖作者选择。

