function adjacentLengthVolatility(lengths) {
  if (lengths.length < 2) return 0
  let sum = 0
  for (let i = 1; i < lengths.length; i += 1) {
    sum += Math.abs(lengths[i] - lengths[i - 1]) / Math.max(lengths[i - 1], 1)
