    if (match) starts.push(value.slice(match.index, match.index + 2))
  }
  return starts
}

function adjacentLengthVolatility(lengths) {
  if (lengths.length < 2) return 0
  let sum = 0
  for (let i = 1; i < lengths.length; i += 1) {
    sum += Math.abs(lengths[i] - lengths[i - 1]) / Math.max(lengths[i - 1], 1)
  }
  return sum / (lengths.length - 1)
}

function countWordList(text, words) {
  let count = 0
  for (const word of words) count += text.split(word).length - 1
  return count
}

function median(values) {
  if (values.length === 0) return 0
  const sorted = [...values].sort((a, b) => a - b)
  const middle = Math.floor(sorted.length / 2)
  return sorted.length % 2 === 0 ? (sorted[middle - 1] + sorted[middle]) / 2 : sorted[middle]
}

