// 只统计 CJK 字符；句子按 。！？ 与换行切分；段落按空行/换行切分。

function countCjk(text) {
  return (text.match(/[\u3400-\u9fff\uf900-\ufaff]/g) || []).length
}

function splitSentences(body) {
  return body
    .split(/[。！？!?；;…\n]+/)
    .map((sentence) => sentence.trim())
    .filter((sentence) => /[\u3400-\u9fff\uf900-\ufaff]/.test(sentence))
}

function splitParagraphs(body) {
  return body
    .split(/\n+/)
    .map((paragraph) => paragraph.trim())
    .filter(Boolean)
}

function sentenceLengths(body) {
  return splitSentences(body).map((sentence) => countCjk(sentence))
}

function paragraphLengths(body) {
  return splitParagraphs(body).map((paragraph) => countCjk(paragraph))
}

function coefficientOfVariation(values) {
  if (values.length === 0) return 0
  const mean = values.reduce((sum, value) => sum + value, 0) / values.length
  if (mean === 0) return 0
  const variance = values.reduce((sum, value) => sum + (value - mean) ** 2, 0) / values.length
  return Math.sqrt(variance) / mean
}

function startRepeatRatio(starts) {
  if (starts.length < 2) return 0
  const seen = new Set()
  let repeated = 0
  for (const start of starts) {
    if (seen.has(start)) repeated += 1
    else seen.add(start)
  }
  return repeated / starts.length
}

function duplicateSentenceRatio(body) {
  const normalized = splitSentences(body).map((sentence) => normalizeCjk(sentence))
  if (normalized.length === 0) return 0
  return (normalized.length - new Set(normalized).size) / normalized.length
}

function repeatedFourGramRatio(body) {
  let total = 0
  const grams = new Set()
  for (const sentence of splitSentences(body)) {
    const normalized = normalizeCjk(sentence)
    if (normalized.length < 8) continue
    for (let i = 0; i + 4 <= normalized.length; i += 1) {
      total += 1
      grams.add(normalized.slice(i, i + 4))
    }
  }
  return total === 0 ? 0 : (total - grams.size) / total
}

function normalizeCjk(text) {
  return (text.match(/[\u3400-\u9fff\uf900-\ufaff]/g) || []).join("")
}

function cjkStarts(values) {
  const starts = []
  for (const value of values) {
    const match = value.match(/[\u3400-\u9fff\uf900-\ufaff]/)
    if (match) starts.push(value.slice(match.index, match.index + 2))
  }
  return starts
}

function adjacentLengthVolatility(lengths) {
  if (lengths.length < 2) return 0
  let sum = 0
  for (let i = 1; i < lengths.length; i += 1) {
    sum += Math.abs(lengths[i] - lengths[i - 1]) / Math.max(lengths[i - 1], 1)
  }
  return sum / (lengths.length - 1)
}

function countWordList(text, words) {
  let count = 0
  for (const word of words) count += text.split(word).length - 1
  return count
}

function median(values) {
  if (values.length === 0) return 0
  const sorted = [...values].sort((a, b) => a - b)
  const middle = Math.floor(sorted.length / 2)
  return sorted.length % 2 === 0 ? (sorted[middle - 1] + sorted[middle]) / 2 : sorted[middle]
}

function computeBaselineMetrics(body) {
  const chineseChars = countCjk(body)
  if (chineseChars < 800) {
    return { chineseChars, enabled: false }
  }
  const sentences = splitSentences(body)
